async init() {
  try {
    if (!this.element) await this.createElement();
    await Promise.all([this.setupData(), this.setupEventListeners()]);
    await this.render();
  } catch (error) {
    this.logError('Initialization failed', error);
    throw error;
  }
}

async request(endpoint, options) {
  const token = appStore.getState().user.token;
  if (token) options.headers.Authorization = `Bearer ${token}`;
  try {
    const response = await fetch(url, options);
    const data = await response.json();
    return data.success ? data.data : data;
  } catch (error) {
    this.handleError(error);
  }
}

setupStateObservers() {
  this.unsubscribers = [];
  const unsubscribe = appStore.subscribe('state:changed', (event, data) => {
    if (data.changes['data.toilets']) {
      this.update({ toilets: data.changes['data.toilets'].to });
    }
  });
  this.unsubscribers.push(unsubscribe);
}
cleanupStateObservers() {
  this.unsubscribers.forEach(fn => fn());
}

async initializeMap() {
  if (typeof L === 'undefined') throw new Error('Leaflet not loaded');
  const mapElement = $('#map');
  mapElement.style.height = '500px';
  this.map = L.map(mapElement, {...config});
  L.tileLayer(url, options).addTo(this.map);
  setTimeout(() => this.map.invalidateSize(), 100);
}

async initializeQRScanner() {
  if (typeof Html5Qrcode === 'undefined') throw new Error('Library not loaded');
  if (this.qrScanner) await this.qrScanner.clear();
  this.qrScanner = new Html5QrcodeScanner(id, config);
  try {
    this.qrScanner.render(onSuccess, onFailure);
  } catch (error) {
    this.handleScannerError(error);
  }
}

async setupEventListeners() {
  const cleanup = this.addEventListener('click', handler);
  this.eventListeners.set('click_handler', cleanup);
}
cleanupEventListeners() {
  this.eventListeners.forEach(cleanup => cleanup());
  this.eventListeners.clear();
}

async loadData() {
  const abortController = new AbortController();
  this.currentRequest = abortController;
  try {
    const data = await fetch(url, { signal: abortController.signal });
    if (!this.destroyed) this.setState({ data });
  } catch (error) {
    if (error.name !== 'AbortError') throw error;
  }
}
destroy() {
  if (this.currentRequest) this.currentRequest.abort();
}

async handleSubmit(event) {
  event.preventDefault();
  if (!this.validateForm()) return;
  const btn = event.target.querySelector('button[type="submit"]');
  btn.disabled = true;
  try {
    await this.submitForm();
    event.target.reset();
    this.showSuccess();
  } catch (error) {
    this.showError(error.message);
  } finally {
    btn.disabled = false;
  }
}
